      "path": "integrations/dsh/package.json",
      "content": "{\n  \"name\": \"@agentscope-ai/reme-dsh-plugin\",\n  \"version\": \"0.1.3\",\n  \"description\": \"ReMe memory and context integration for DeepSeek Harness\",\n  \"type\": \"module\",\n  \"main\": \"./dist/index.js\",\n  \"types\": \"./dist/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"import\": \"./dist/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./dist/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"dist\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README_ZH.md\",\n    \"figures\"\n  ],\n  \"dsh\": {\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\",\n        \"@deepseek-ai/dsh-client-ui-primitives\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"npm run clean && tsc -p tsconfig.json && node scripts/build-client.mjs\",\n    \"clean\": \"node -e \\\"require('node:fs').rmSync('dist', { force: true, recursive: true })\\\"\",\n    \"format\": \"prettier --write .\",\n    \"format:check\": \"prettier --check .\",\n    \"lint\": \"eslint .\",\n    \"pretest\": \"npm run build\",\n    \"test\": \"node --test tests/*.test.mjs\",\n    \"test:package\": \"node scripts/test-package.mjs\",\n    \"prepare\": \"npm run build\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4 || ^4.0.5-alpha.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.1.7-rc.2 || ^0.2.0-rc.2 || ^0.2.1-alpha.2\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.7-rc.2 || ^0.2.0-rc.2 || ^0.2.1-alpha.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.7-rc.2 || ^0.2.0-rc.2 || ^0.2.1-alpha.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"^0.1.7-rc.2 || ^0.2.0-rc.2 || ^0.2.1-alpha.2\",\n    \"@deepseek-ai/schemastery\": \"~3.18.4 || ^3.18.5-alpha.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-typert-protocol\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"1.0.6\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@eslint/js\": \"9.39.4\",\n    \"@types/node\": \"^22.15.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"esbuild\": \"^0.25.10\",\n    \"eslint\": \"9.39.4\",\n    \"eslint-plugin-react-hooks\": \"7.1.1\",\n    \"globals\": \"16.4.0\",\n    \"prettier\": \"3.0.0\",\n    \"react\": \"^18.2.0\",\n    \"typescript\": \"^5.9.2\",\n    \"typescript-eslint\": \"8.59.3\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.2.1-rc.2\",\n    \"react-test-renderer\": \"^18.3.1\",\n    \"semver\": \"^7.8.5\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/agentscope-a